/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> grooveKickSixteenthsLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "Rock and funk grooves get their personality from where the kick falls between the eighths. Moving one kick to the \"e\" or the \"a\" of a beat changes the whole feel while the hands stay the same, and each of these patterns is one you will meet on records.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Hi-hat eighths and backbeat on 2 and 4 stay fixed. Line 1 puts the kick on 1, the \"a\" of 2, 3 and the \"a\" of 4; each \"a\" is the sixteenth right before the next beat and falls between two hi-hat notes. Heel up, short strokes, and land the \"a\" exactly halfway between the hat strokes.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 2 moves the extra kicks to the \"e\" of 2 and 4, line 3 doubles them on 1 and 3 (\"1 a\", \"3 a\"), line 4 plays 1, 3, the \"a\" of 3 and the \"and\" of 4. Lines 5 and 6 switch to sixteenth hats so every kick has a hat partner, with ghost notes on the snare. Line 7 is half-time with the backbeat on 3, line 8 opens with a crash. Count the sixteenths aloud before you play a line.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Rock and funk records everywhere: Zigaboo Modeliste with the Meters, Jeff Porcaro with Toto, John Bonham with Led Zeppelin and Chad Smith with the Red Hot Chili Peppers all lean on kicks on the \"e\" and the \"a\".",
